package com.cpf.batch.control.deploy; import com.cpf.batch.api.*; import com.cpf.batch.spi.DeploymentTargetAdapter; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.util.Set;
@Component public class HostAgentDeploymentAdapter implements DeploymentTargetAdapter { private static final Set<String> HOST_AGENT_MODES=Set.of("embedded-bootjar","external-tomcat-war");private final RestClient.Builder b;public HostAgentDeploymentAdapter(RestClient.Builder b){this.b=b;}public boolean supports(DeploymentCellManifest.Instance i,String mode){return i.agentBaseUrl()!=null&&!i.agentBaseUrl().isBlank()&&mode!=null&&HOST_AGENT_MODES.contains(mode.toLowerCase(java.util.Locale.ROOT));}public DeploymentResult.InstanceResult deploy(DeploymentCellManifest m,DeploymentCellManifest.Instance i){try{AgentArtifactRequest q=new AgentArtifactRequest(m.serviceId(),m.artifact().coordinate(),m.artifact().version(),m.artifact().sha256(),m.artifact().signatureBase64(),m.runtimeMode(),i.configRef(),"cpf-batch-control-server","approved deployment "+m.cellId());AgentCommandResult r=b.baseUrl(i.agentBaseUrl()).build().post().uri("/api/v1/agent/artifacts/install").body(q).retrieve().body(AgentCommandResult.class);if(r==null||r.state()!=CommandState.SUCCEEDED)return new DeploymentResult.InstanceResult(i.instanceId(),r==null?CommandState.UNKNOWN_RESULT:r.state(),"INSTALL",r==null?"No result":r.message());return start(m,i);}catch(RuntimeException e){return new DeploymentResult.InstanceResult(i.instanceId(),CommandState.UNKNOWN_RESULT,"INSTALL",e.getClass().getSimpleName());}}public DeploymentResult.InstanceResult rollback(DeploymentCellManifest m,DeploymentCellManifest.Instance i){return cmd(m,i,"ROLLBACK");}public DeploymentResult.InstanceResult start(DeploymentCellManifest m,DeploymentCellManifest.Instance i){return cmd(m,i,"START");}public DeploymentResult.InstanceResult stop(DeploymentCellManifest m,DeploymentCellManifest.Instance i){return cmd(m,i,"STOP");}public DeploymentResult.InstanceResult drain(DeploymentCellManifest m,DeploymentCellManifest.Instance i){return cmd(m,i,"DRAIN");}public DeploymentResult.InstanceResult resume(DeploymentCellManifest m,DeploymentCellManifest.Instance i){return cmd(m,i,"RESUME");}private DeploymentResult.InstanceResult cmd(DeploymentCellManifest m,DeploymentCellManifest.Instance i,String op){try{AgentCommandResult r=b.baseUrl(i.agentBaseUrl()).build().post().uri("/api/v1/agent/services/{service}/{op}",m.serviceId(),op.toLowerCase()).retrieve().body(AgentCommandResult.class);return new DeploymentResult.InstanceResult(i.instanceId(),r==null?CommandState.UNKNOWN_RESULT:r.state(),op,r==null?"No result":r.message());}catch(RuntimeException e){return new DeploymentResult.InstanceResult(i.instanceId(),CommandState.UNKNOWN_RESULT,op,e.getClass().getSimpleName());}} }
